function wireCost(points: number[][]): number {
  const n = points.length, edges: number[][] = [];
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      edges.push([Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]), i, j]);
  edges.sort((a, b) => a[0] - b[0]);
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x: number): number => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  let total = 0, used = 0;
  for (const [d, i, j] of edges) {
    if (used === n - 1) break;
    const a = find(i), b = find(j);
    if (a === b) continue; // already connected: this cable would close a loop
    parent[a] = b;
    total += d;
    used++;
  }
  return total;
}

