class Solution:
    def wireCost(self, points: List[List[int]]) -> int:
        n = len(points)
        edges = []
        for i in range(n):
            xi, yi = points[i]
            for j in range(i + 1, n):
                edges.append((abs(xi - points[j][0]) + abs(yi - points[j][1]), i, j))
        edges.sort()
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        total = used = 0
        for d, i, j in edges:
            if used == n - 1:
                break
            a, b = find(i), find(j)
            if a == b:
                continue
            parent[a] = b
            total += d
            used += 1
        return total

