function wireCost(points: number[][]): number {
  const n = points.length;
  const best = new Array(n).fill(Infinity), wired = new Array(n).fill(false);
  best[0] = 0;
  let total = 0;
  for (let round = 0; round < n; round++) {
    let u = -1;
    for (let v = 0; v < n; v++) if (!wired[v] && (u === -1 || best[v] < best[u])) u = v;
    wired[u] = true;
    total += best[u];
    const [x, y] = points[u];
    for (let v = 0; v < n; v++) {
      if (wired[v]) continue;
      const d = Math.abs(x - points[v][0]) + Math.abs(y - points[v][1]);
      if (d < best[v]) best[v] = d;
    }
  }
  return total;
}

